<?php require_once __DIR__ . '/includes/config.php';role(['admin','auditor']);$rows=db()->query('SELECT a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200')->fetchAll();head('Audit log');?><h1>Audit log</h1><div class="panel table"><table><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['username']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td></tr><?php endforeach;?></table></div><?php foot();?>